import test from 'node:test';
import assert from 'node:assert/strict';
import {lockScopeRows,parseLockComment,validateLockPlan,validateLockResult,lockResultSummary} from '../web/model.js';
const rows=[{id:'a',path:'shown/a',item:'modified',props:'none',changelist:'x'},{id:'b',path:'hidden/b',item:'normal',props:'none',changelist:'x'}];
const request={workspaceId:'w',selectionVersion:1,snapshotToken:'s',action:'lock',comment:'',ids:['a','b']};
const plan={...request,mode:'live',planToken:'p',expiresIn:120,contactsRepository:true,files:rows.map(r=>({...r,fromChangelist:'x',locked:false,ownedByWorkingCopy:false,localTokenPresent:false,staleLocalToken:false,workingRevision:'2',serverLastChangedRevision:'1'}))};
const result={mode:'live',workspaceId:'w',selectionVersion:1,statusRefreshed:true,snapshotToken:'s2',rows,lockResult:{action:'lock',files:rows.map(r=>r.path),outcome:'verified',verified:true,warnings:[]}};
test('lock exact selection includes hidden rows, rejects missing and unsafe entries',()=>{assert.deepEqual(lockScopeRows(rows,new Set(['a','b'])),rows);assert.throws(()=>lockScopeRows(rows,new Set(['missing'])));for(const patch of [{wc_locked:true},{kind:'dir'},{item:'added'},{file_external:true}])assert.throws(()=>lockScopeRows([{...rows[0],...patch}],new Set(['a'])));});
test('optional comment exact UTF-8 bound; no control chars, passwords or tokens',()=>{assert.equal(parseLockComment('lock',''),'');assert.equal(parseLockComment('lock','a'.repeat(4096)).length,4096);for(const value of ['a'.repeat(4097),'中'.repeat(1366),'\ud800','\u0085','urn:uuid:secret','https://user:password@host/'])assert.throws(()=>parseLockComment('lock',value));assert.throws(()=>parseLockComment('unlock','text'));assert.equal(parseLockComment('unlock',''),'');});
test('preflight validates repository contact, boolean lock state, immutable exact range and TTL',()=>{assert.equal(validateLockPlan(plan,request,rows),plan);for(const patch of [{contactsRepository:false},{comment:'other'},{action:'unlock'},{expiresIn:121},{snapshotToken:'new'},{files:[plan.files[0],plan.files[0]]}])assert.throws(()=>validateLockPlan({...plan,...patch},request,rows));for(const patch of [{locked:true},{localTokenPresent:true},{staleLocalToken:true},{workingRevision:2},{path:'wrong'}])assert.throws(()=>validateLockPlan({...plan,files:[{...plan.files[0],...patch},plan.files[1]]},request,rows));const unlock={...request,action:'unlock'};assert.equal(validateLockPlan({...plan,action:'unlock',files:plan.files.map(f=>({...f,locked:true,ownedByWorkingCopy:true,localTokenPresent:true}))},unlock,rows).action,'unlock');});
test('result validates exact paths and codes; confirmed result survives failed refresh',()=>{assert.equal(validateLockResult(result,request,plan.files),result.lockResult);const failed={...result,statusRefreshed:false,snapshotToken:null,rows:[],lockResult:{...result.lockResult,warnings:['status-refresh-failed']}};assert.match(lockResultSummary(validateLockResult(failed,request,plan.files)),/已核实锁定完成/);for(const patch of [{verified:false},{files:['shown/a']},{warnings:['raw secret']},{warnings:['toString']},{outcome:'success'}])assert.throws(()=>validateLockResult({...result,lockResult:{...result.lockResult,...patch}},request,plan.files));});
test('lock rejects copied/moved/unsupported properties and stale or oversized revisions',()=>{
 for(const patch of [{copied:true},{moved_from:'old'},{moved_to:'new'},{props:'unknown'},{props:undefined}])assert.throws(()=>lockScopeRows([{...rows[0],...patch}],new Set(['a'])));
 for(const patch of [{workingRevision:'9223372036854775808'},{serverLastChangedRevision:'9223372036854775808'},{workingRevision:'0',serverLastChangedRevision:'1'},{workingRevision:'1'.repeat(200)}])assert.throws(()=>validateLockPlan({...plan,files:[{...plan.files[0],...patch},plan.files[1]]},request,rows));
});
